-- Course management (Prompt 7): a course_manager role, file uploads on course requests,
-- and /manage pages for requests and course fixes, every edit recorded in content_audit.
-- Students still cannot publish content: every manager action is a security definer
-- function that checks the caller's role, so RLS and the server block students, not the menu.
-- New courses are still generated by the content pipeline (docs/how-to-add-a-course.md).

-- 1. Roles. Students have no grant on this column, so they can never change it (not even their own);
--    it is set in the database only (scripts/set_role.py, or SQL).
alter table public.profiles
  add column role text not null default 'student' check (role in ('student', 'course_manager'));

create or replace function public.is_course_manager()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'course_manager');
$$;
revoke execute on function public.is_course_manager() from public, anon;
grant execute on function public.is_course_manager() to authenticated;

-- 2. Requests: an "in progress" status, a reason when declined (admin_note), and uploaded files.
alter table public.course_requests drop constraint course_requests_status_check;
alter table public.course_requests add constraint course_requests_status_check
  check (status in ('pending', 'in_progress', 'added', 'declined'));
-- The app picks the request id, so files can be uploaded under it straight after the insert.
grant insert (id) on public.course_requests to authenticated;
create policy "course_requests: managers read all" on public.course_requests
  for select to authenticated using ((select public.is_course_manager()));

create table public.course_request_files (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.course_requests (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  path text not null unique,   -- in the course-request-files bucket: <student id>/<request id>/<file name>
  name text not null check (length(name) between 1 and 200),
  size_bytes bigint not null check (size_bytes between 1 and 20971520),  -- 20 MB
  content_type text not null,
  created_at timestamptz not null default now()
);
create index course_request_files_request_idx on public.course_request_files (request_id);

alter table public.course_request_files enable row level security;
grant select on public.course_request_files to authenticated;
grant insert (request_id, student_id, path, name, size_bytes, content_type) on public.course_request_files to authenticated;
create policy "course_request_files: read own, or any as a manager" on public.course_request_files
  for select to authenticated
  using (student_id = (select auth.uid()) or (select public.is_course_manager()));
create policy "course_request_files: add to own request" on public.course_request_files
  for insert to authenticated
  with check (
    student_id = (select auth.uid())
    and exists (select 1 from public.course_requests r where r.id = request_id and r.student_id = (select auth.uid()))
    and path like (select auth.uid())::text || '/' || request_id::text || '/%'
  );

-- At most 5 files per request.
create or replace function public.course_request_files_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.course_request_files where request_id = new.request_id) >= 5 then
    raise exception 'A request can have at most 5 files' using errcode = '23514';
  end if;
  return new;
end;
$$;
create trigger course_request_files_limit before insert on public.course_request_files
  for each row execute function public.course_request_files_limit();

-- The private bucket: PDF, DOCX, PPTX and images, 20 MB each. Students upload into their own
-- folder and read only their own files; course managers read every file.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('course-request-files', 'course-request-files', false, 20971520, array[
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'image/png', 'image/jpeg', 'image/webp', 'image/heic'
])
on conflict (id) do nothing;

create policy "course request files: upload to own folder" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'course-request-files' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "course request files: read own, or any as a manager" on storage.objects
  for select to authenticated
  using (bucket_id = 'course-request-files'
         and ((storage.foldername(name))[1] = (select auth.uid())::text or (select public.is_course_manager())));

-- 3. Questions can be hidden by a manager (start_quiz only uses approved ones).
alter table public.questions drop constraint questions_status_check;
alter table public.questions add constraint questions_status_check check (status in ('draft', 'approved', 'hidden'));

-- Notifications for request status changes (one kind per status, so each can fire once a day).
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in (
  'streak_at_risk', 'inactive_3_days', 'daily_goal_reached', 'score_improved',
  'new_recommendations', 'weak_topic_unstudied', 'course_added',
  'course_request_in_progress', 'course_request_declined'
));

-- 4. Every manager edit: who, when, what changed. Managers read it; only the functions below write it.
create table public.content_audit (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references public.profiles (id) on delete set null,
  action text not null,        -- e.g. topic.update, question.hide, request.status
  table_name text not null,
  row_id uuid not null,
  summary text not null,       -- one line for people, e.g. "CSC 531 / Topic 2: summary"
  changes jsonb not null,      -- {"field": {"from": ..., "to": ...}}
  created_at timestamptz not null default now()
);
create index content_audit_created_idx on public.content_audit (created_at desc);
create index content_audit_row_idx on public.content_audit (table_name, row_id);
alter table public.content_audit enable row level security;
grant select on public.content_audit to authenticated;
create policy "content_audit: managers read" on public.content_audit
  for select to authenticated using ((select public.is_course_manager()));

-- Raises unless the caller is a course manager.
create or replace function public.require_course_manager()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_course_manager() then
    raise exception 'course managers only' using errcode = '42501';
  end if;
  return auth.uid();
end;
$$;

-- {"field": {"from", "to"}} for the fields whose value changed.
create or replace function public.audit_changes(p_old jsonb, p_new jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_object_agg(k, jsonb_build_object('from', p_old -> k, 'to', p_new -> k)), '{}'::jsonb)
  from jsonb_object_keys(p_new) k
  where (p_old -> k) is distinct from (p_new -> k);
$$;

create or replace function public.write_audit(p_action text, p_table text, p_row uuid, p_summary text, p_changes jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.content_audit (actor_id, action, table_name, row_id, summary, changes)
  values (auth.uid(), p_action, p_table, p_row, p_summary, p_changes);
$$;

-- A question's options and answer have the shape submit_quiz expects.
create or replace function public.question_shape_ok(p_format text, p_options jsonb, p_correct jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  with opts as (select o ->> 'key' as k, o ->> 'text' as t from jsonb_array_elements(p_options) o),
       ans as (select a #>> '{}' as k from jsonb_array_elements(p_correct) a)
  select jsonb_typeof(p_options) = 'array' and jsonb_typeof(p_correct) = 'array'
     and (select count(*) from opts) >= 2
     and not exists (select 1 from opts where coalesce(k, '') = '' or coalesce(trim(t), '') = '')
     and (select count(distinct k) from opts) = (select count(*) from opts)
     and (select count(*) from ans) >= 1
     and not exists (select 1 from ans where k not in (select k from opts))
     and (select count(distinct k) from ans) = (select count(*) from ans)
     and case p_format
           when 'single_choice' then (select count(*) from ans) = 1
           when 'odd_one_out' then (select count(*) from ans) = 1 and (select count(*) from opts) >= 3
           when 'true_false' then (select count(*) from ans) = 1
                                  and (select array_agg(k order by k) from opts) = array['false', 'true']
           when 'multi_select' then (select count(*) from ans) >= 2
           else false
         end;
$$;

-- 5. Manager functions. Each checks the role, changes one thing and writes one audit row.

-- Every request, newest first, with the student's name and email and the files.
create or replace function public.manage_requests()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_course_manager();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'code', r.code, 'title', r.title, 'level', r.level, 'semester', r.semester,
      'lecturer', r.lecturer, 'details', r.details, 'status', r.status, 'admin_note', r.admin_note,
      'course_id', r.course_id, 'created_at', r.created_at, 'updated_at', r.updated_at,
      'student', jsonb_build_object('id', p.id, 'name', p.full_name, 'email', u.email),
      'files', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'path', f.path, 'name', f.name,
                                                             'size_bytes', f.size_bytes, 'content_type', f.content_type)
                                          order by f.created_at)
                         from public.course_request_files f where f.request_id = r.id), '[]'::jsonb)
    ) order by r.created_at desc)
    from public.course_requests r
    join public.profiles p on p.id = r.student_id
    left join auth.users u on u.id = r.student_id
  ), '[]'::jsonb);
end;
$$;

-- Mark a request in progress, added (optionally linking the course and enrolling the student)
-- or declined (a reason is required). The student is notified each time.
create or replace function public.manage_set_request_status(
  p_request uuid, p_status text, p_note text default null, p_course_code text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.course_requests;
  v_course public.courses;
begin
  perform public.require_course_manager();
  if p_status not in ('in_progress', 'added', 'declined') then
    raise exception 'status must be in_progress, added or declined' using errcode = '22023';
  end if;
  if p_status = 'declined' and coalesce(trim(p_note), '') = '' then
    raise exception 'a reason is required to decline a request' using errcode = '22023';
  end if;
  select * into v_req from public.course_requests where id = p_request for update;
  if not found then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if p_course_code is not null then
    select * into v_course from public.courses where upper(code) = upper(trim(p_course_code));
    if not found then
      raise exception 'no course %', p_course_code using errcode = 'P0002';
    end if;
  end if;

  update public.course_requests
  set status = p_status,
      admin_note = case when p_note is not null then trim(p_note) else admin_note end,
      course_id = coalesce(v_course.id, course_id),
      updated_at = now()
  where id = p_request;

  if p_status = 'added' and v_course.id is not null then
    insert into public.enrollments (student_id, course_id) values (v_req.student_id, v_course.id)
    on conflict do nothing;
  end if;

  insert into public.notifications (student_id, kind, title, body, link)
  values (
    v_req.student_id,
    case p_status when 'added' then 'course_added' when 'declined' then 'course_request_declined'
                  else 'course_request_in_progress' end,
    case p_status when 'added' then format('%s is ready', coalesce(v_course.code, v_req.code))
                  when 'declined' then format('Your request for %s was declined', v_req.code)
                  else format('We are working on %s', v_req.code) end,
    case p_status
      when 'added' then format('%s: %s is now in the app%s.', coalesce(v_course.code, v_req.code),
                               coalesce(v_course.title, v_req.title),
                               case when v_course.id is not null then ' and in your courses' else '' end)
      when 'declined' then format('Reason: %s', trim(p_note))
      else format('Your request for %s: %s is in progress.', v_req.code, v_req.title) end,
    case p_status when 'added' then coalesce('/courses/' || v_course.code, '/courses') else '/courses/request' end
  )
  on conflict do nothing;

  perform public.write_audit('request.status', 'course_requests', p_request,
    format('Request %s: %s', v_req.code, p_status),
    public.audit_changes(jsonb_build_object('status', v_req.status, 'admin_note', v_req.admin_note, 'course_id', v_req.course_id),
                         jsonb_build_object('status', p_status,
                                            'admin_note', case when p_note is not null then trim(p_note) else v_req.admin_note end,
                                            'course_id', coalesce(v_course.id, v_req.course_id))));
end;
$$;

-- A topic's title and summary.
create or replace function public.manage_update_topic(p_topic uuid, p_title text, p_summary text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.topics;
  v_code text;
begin
  perform public.require_course_manager();
  if coalesce(trim(p_title), '') = '' then
    raise exception 'a topic needs a title' using errcode = '22023';
  end if;
  select * into v from public.topics where id = p_topic;
  if not found then
    raise exception 'topic not found' using errcode = 'P0002';
  end if;
  select code into v_code from public.courses where id = v.course_id;
  update public.topics set title = trim(p_title), summary = nullif(trim(p_summary), '') where id = p_topic;
  perform public.write_audit('topic.update', 'topics', p_topic, format('%s / %s', v_code, trim(p_title)),
    public.audit_changes(jsonb_build_object('title', v.title, 'summary', v.summary),
                         jsonb_build_object('title', trim(p_title), 'summary', nullif(trim(p_summary), ''))));
end;
$$;

-- A topic's practice questions, with answers, for managers.
create or replace function public.manage_questions(p_topic uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_course_manager();
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', q.id, 'format', q.format, 'stem', q.stem, 'options', q.options,
                                        'correct_answer', q.correct_answer, 'explanation', q.explanation,
                                        'source', q.source, 'status', q.status) order by q.status, q.stem)
    from public.questions q where q.topic_id = p_topic and q.status <> 'draft'
  ), '[]'::jsonb);
end;
$$;

-- Edit a question's wording, options, answer or explanation (shape checked as submit_quiz needs it).
create or replace function public.manage_update_question(
  p_question uuid, p_stem text, p_options jsonb, p_correct jsonb, p_explanation text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.questions;
  v_where text;
begin
  perform public.require_course_manager();
  select * into v from public.questions where id = p_question;
  if not found then
    raise exception 'question not found' using errcode = 'P0002';
  end if;
  if coalesce(trim(p_stem), '') = '' or coalesce(trim(p_explanation), '') = '' then
    raise exception 'a question needs a stem and an explanation' using errcode = '22023';
  end if;
  if not public.question_shape_ok(v.format, p_options, p_correct) then
    raise exception 'options and correct answer do not fit a % question', v.format using errcode = '22023';
  end if;
  update public.questions
  set stem = trim(p_stem), options = p_options, correct_answer = p_correct, explanation = trim(p_explanation)
  where id = p_question;
  select c.code || ' / ' || t.title into v_where from public.topics t join public.courses c on c.id = t.course_id where t.id = v.topic_id;
  perform public.write_audit('question.update', 'questions', p_question, format('%s: question edited', v_where),
    public.audit_changes(jsonb_build_object('stem', v.stem, 'options', v.options, 'correct_answer', v.correct_answer, 'explanation', v.explanation),
                         jsonb_build_object('stem', trim(p_stem), 'options', p_options, 'correct_answer', p_correct, 'explanation', trim(p_explanation))));
end;
$$;

-- Hide a question from quizzes, or show it again.
create or replace function public.manage_set_question_hidden(p_question uuid, p_hidden boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.questions;
  v_where text;
  v_status text := case when p_hidden then 'hidden' else 'approved' end;
begin
  perform public.require_course_manager();
  select * into v from public.questions where id = p_question;
  if not found or v.status = 'draft' then
    raise exception 'question not found' using errcode = 'P0002';
  end if;
  update public.questions set status = v_status where id = p_question;
  select c.code || ' / ' || t.title into v_where from public.topics t join public.courses c on c.id = t.course_id where t.id = v.topic_id;
  perform public.write_audit(case when p_hidden then 'question.hide' else 'question.show' end, 'questions', p_question,
    format('%s: question %s', v_where, case when p_hidden then 'hidden' else 'shown again' end),
    public.audit_changes(jsonb_build_object('status', v.status), jsonb_build_object('status', v_status)));
end;
$$;

-- Add a link resource to a topic, or fix an existing resource's title or link.
create or replace function public.manage_save_resource(
  p_resource uuid, p_topic uuid, p_title text, p_type text, p_url text, p_link_type text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.resources;
  v_id uuid;
  v_where text;
begin
  perform public.require_course_manager();
  if coalesce(trim(p_title), '') = '' then
    raise exception 'a resource needs a title' using errcode = '22023';
  end if;
  if p_url is not null and trim(p_url) <> '' and trim(p_url) !~ '^https?://' then
    raise exception 'links must start with http:// or https://' using errcode = '22023';
  end if;
  if p_resource is null then
    if p_type not in ('lecture', 'video', 'textbook', 'past_questions') or coalesce(trim(p_url), '') = '' then
      raise exception 'a new resource needs a link and a type (lecture, video, textbook or past_questions)' using errcode = '22023';
    end if;
    insert into public.resources (topic_id, title, type, url, link_type, source)
    values (p_topic, trim(p_title), p_type, trim(p_url), case when p_type = 'textbook' then p_link_type end,
            'Added by a course manager')
    returning id into v_id;
    v := null;
  else
    select * into v from public.resources where id = p_resource;
    if not found then
      raise exception 'resource not found' using errcode = 'P0002';
    end if;
    update public.resources
    set title = trim(p_title),
        url = nullif(trim(p_url), ''),
        link_type = case when v.type = 'textbook' and nullif(trim(p_url), '') is not null then p_link_type end
    where id = p_resource;
    v_id := p_resource;
  end if;
  select c.code || ' / ' || t.title into v_where from public.topics t join public.courses c on c.id = t.course_id
  where t.id = coalesce(v.topic_id, p_topic);
  perform public.write_audit(case when p_resource is null then 'resource.add' else 'resource.update' end, 'resources', v_id,
    format('%s: %s', v_where, trim(p_title)),
    public.audit_changes(jsonb_build_object('title', v.title, 'url', v.url, 'link_type', v.link_type),
                         jsonb_build_object('title', trim(p_title), 'url', nullif(trim(p_url), ''),
                                            'link_type', case when coalesce(v.type, p_type) = 'textbook' then p_link_type end)));
  return v_id;
end;
$$;

-- Mark a course reviewed (removes the "Sample content" badge), or back to sample.
create or replace function public.manage_set_course_reviewed(p_course uuid, p_reviewed boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.courses;
begin
  perform public.require_course_manager();
  select * into v from public.courses where id = p_course;
  if not found then
    raise exception 'course not found' using errcode = 'P0002';
  end if;
  update public.courses set is_reviewed = p_reviewed where id = p_course;
  perform public.write_audit(case when p_reviewed then 'course.review' else 'course.unreview' end, 'courses', p_course,
    format('%s marked %s', v.code, case when p_reviewed then 'reviewed' else 'sample content' end),
    public.audit_changes(jsonb_build_object('is_reviewed', v.is_reviewed), jsonb_build_object('is_reviewed', p_reviewed)));
end;
$$;

-- The audit trail with each editor's name, newest first.
create or replace function public.manage_audit(p_limit int default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_course_manager();
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', a.id, 'action', a.action, 'summary', a.summary, 'changes', a.changes,
                                        'created_at', a.created_at, 'actor', p.full_name) order by a.created_at desc)
    from (select * from public.content_audit order by created_at desc limit least(greatest(p_limit, 1), 500)) a
    left join public.profiles p on p.id = a.actor_id
  ), '[]'::jsonb);
end;
$$;

-- Internal helpers: nobody calls them directly.
revoke execute on function public.require_course_manager() from public, anon, authenticated;
revoke execute on function public.audit_changes(jsonb, jsonb) from public, anon, authenticated;
revoke execute on function public.write_audit(text, text, uuid, text, jsonb) from public, anon, authenticated;
revoke execute on function public.question_shape_ok(text, jsonb, jsonb) from public, anon, authenticated;
revoke execute on function public.course_request_files_limit() from public, anon, authenticated;

-- The manager functions: callable by any signed-in user, but each raises 42501 unless the caller is a manager.
revoke execute on function public.manage_requests() from public, anon;
revoke execute on function public.manage_set_request_status(uuid, text, text, text) from public, anon;
revoke execute on function public.manage_update_topic(uuid, text, text) from public, anon;
revoke execute on function public.manage_questions(uuid) from public, anon;
revoke execute on function public.manage_update_question(uuid, text, jsonb, jsonb, text) from public, anon;
revoke execute on function public.manage_set_question_hidden(uuid, boolean) from public, anon;
revoke execute on function public.manage_save_resource(uuid, uuid, text, text, text, text) from public, anon;
revoke execute on function public.manage_set_course_reviewed(uuid, boolean) from public, anon;
revoke execute on function public.manage_audit(int) from public, anon;
grant execute on function public.manage_requests() to authenticated;
grant execute on function public.manage_set_request_status(uuid, text, text, text) to authenticated;
grant execute on function public.manage_update_topic(uuid, text, text) to authenticated;
grant execute on function public.manage_questions(uuid) to authenticated;
grant execute on function public.manage_update_question(uuid, text, jsonb, jsonb, text) to authenticated;
grant execute on function public.manage_set_question_hidden(uuid, boolean) to authenticated;
grant execute on function public.manage_save_resource(uuid, uuid, text, text, text, text) to authenticated;
grant execute on function public.manage_set_course_reviewed(uuid, boolean) to authenticated;
grant execute on function public.manage_audit(int) to authenticated;
